package com.nth.desktop3d;

import android.content.Context;
import android.util.AtomicFile;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;

/** Private, named workspace snapshots. Immutable blobs are committed through one atomic index. */
final class DesktopPresets {
    static final int MAX_PRESETS=12;static final long MAX_TOTAL_BYTES=64L*1024*1024;
    private static final Object LOCK=new Object();private static final int INDEX_BYTES=1024*1024;
    private final Context context;private final File directory;
    static final class Entry {
        final JSONObject json;final String id,name,blob;final int scene,source,pages,folders,shortcuts,widgets,cards;final long saved,bytes;
        Entry(JSONObject j)throws Exception {
            json=new JSONObject(j.toString());id=j.getString("id");blob=j.getString("blob");name=PresetNames.checked(j.getString("name"));
            if(!PresetNames.identifier(id)||!PresetNames.identifier(blob)||!j.getString("sha256").matches("[0-9a-f]{64}"))throw new IOException("Invalid preset identity");
            scene=DesktopBackup.integer(j,"scene",0,LauncherStore.MODES.length-1);source=DesktopBackup.integer(j,"source",0,3);pages=DesktopBackup.integer(j,"pages",1,LauncherStore.MAX_PAGES);folders=DesktopBackup.integer(j,"folders",0,20000);shortcuts=DesktopBackup.integer(j,"shortcuts",0,20000);widgets=DesktopBackup.integer(j,"widgets",0,300);cards=j.has("cards")?DesktopBackup.integer(j,"cards",0,192):0;bytes=DesktopBackup.integer(j,"bytes",1,DesktopBackup.MAX_BYTES);saved=j.getLong("saved");if(saved<0)throw new IOException("Invalid preset date");ids(j);if(j.has("shortcutKeys")){JSONArray keys=j.getJSONArray("shortcutKeys");if(keys.length()>20000)throw new IOException("Too many saved shortcuts");for(int i=0;i<keys.length();i++){String key=DesktopBackup.text(new JSONObject().put("key",keys.get(i)),"key",2048);if(!key.startsWith("shortcut:"))throw new IOException("Invalid saved shortcut");}}
        }
        String sceneName(){return source==1?"Photo wallpaper":source==2?"Android wallpaper":source==3?"My layered scene":LauncherStore.MODES[scene];}
        String summary(){return sceneName()+" · "+pages+" desktops · "+folders+" folders · "+shortcuts+" shortcuts"+(cards>0?" · "+cards+" cards":"")+(widgets>0?" · "+widgets+" widgets":"");}
    }
    static final class Listing {final List<Entry> entries;final boolean undo;Listing(List<Entry> entries,boolean undo){this.entries=entries;this.undo=undo;}}
    static final class Snapshot {
        final byte[] bytes;final DesktopBackup.Prepared prepared;final Set<Integer> widgetIds;final Set<String> shortcutKeys=new HashSet<>();final int scene,source;
        Snapshot(JSONObject document,SettingsModel model)throws Exception {
            JSONObject copy=new JSONObject(document.toString());copy.put("note","");prepared=new DesktopBackup.Prepared(copy,model);bytes=copy.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>DesktopBackup.MAX_BYTES)throw new IOException("This desktop is too large for a preset");
            JSONObject values=copy.getJSONObject("settings").getJSONObject("values");scene=values.getInt("scene");source=values.getInt("wallpaper_source");widgetIds=new HashSet<>();for(int i=0;i<prepared.widgets.length();i++){int id=prepared.widgets.getJSONObject(i).getInt("id");if(id>=0)widgetIds.add(id);}
            for(List<LauncherStore.Item> page:prepared.pages)for(LauncherStore.Item item:page)shortcuts(item);for(int i=0;i<prepared.dock.length();i++)if(prepared.dock.getJSONObject(i).has("item"))shortcuts(LauncherStore.Item.read(prepared.dock.getJSONObject(i).getJSONObject("item"),0));
        }
        private void shortcuts(LauncherStore.Item item){if(PinnedShortcuts.isShortcut(item))shortcutKeys.add(item.key);for(LauncherStore.Item child:item.children)shortcuts(child);}
    }
    DesktopPresets(Context context){this.context=context;directory=new File(context.getFilesDir(),"desktop-presets");}
    private AtomicFile index(){return new AtomicFile(new File(directory,"index.json"));}
    private File blob(String id)throws IOException {if(!PresetNames.identifier(id))throw new IOException("Invalid preset identity");return new File(directory,id+".json");}
    private JSONObject readIndex()throws Exception {
        JSONObject j;if(!index().getBaseFile().exists()&&!new File(directory,"index.json.bak").exists()){File[] files=directory.listFiles();if(files!=null)for(File file:files){String name=file.getName();if(name.endsWith(".json")&&PresetNames.identifier(name.substring(0,name.length()-5)))throw new IOException("Saved preset index is missing");}j=new JSONObject().put("format","nth-desktop-presets").put("version",1).put("entries",new JSONArray()).put("gc",new JSONArray());}
        else try(InputStream in=index().openRead()){j=new JSONObject(new String(WallpaperStore.read(in,INDEX_BYTES),StandardCharsets.UTF_8));}
        if(!"nth-desktop-presets".equals(j.getString("format"))||j.getInt("version")!=1)throw new IOException("Unsupported preset collection");JSONArray entries=j.getJSONArray("entries");if(entries.length()>MAX_PRESETS)throw new IOException("Too many presets");Set<String> unique=new HashSet<>();List<String> names=new ArrayList<>();long bytes=0;
        for(int i=0;i<entries.length();i++){Entry e=new Entry(entries.getJSONObject(i));if(!unique.add(e.id))throw new IOException("Duplicate preset");for(String name:names)if(PresetNames.same(name,e.name))throw new IOException("Duplicate preset name");names.add(e.name);bytes+=e.bytes;}
        if(j.has("undo"))bytes+=new Entry(j.getJSONObject("undo")).bytes;if(bytes>MAX_TOTAL_BYTES)throw new IOException("Preset collection is too large");if(j.getJSONArray("gc").length()>10000)throw new IOException("Invalid widget cleanup queue");return j;
    }
    private void write(AtomicFile file,byte[] bytes)throws IOException {if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("Could not create the preset folder");FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);file.finishWrite(out);}catch(IOException error){if(out!=null)file.failWrite(out);throw error;}}
    private void initialize(JSONObject current)throws Exception {if(!index().getBaseFile().exists())write(index(),current.toString().getBytes(StandardCharsets.UTF_8));}
    private void checkBudget(JSONObject index)throws Exception {
        long total=0;JSONArray entries=index.getJSONArray("entries");for(int i=0;i<entries.length();i++)total+=entries.getJSONObject(i).getLong("bytes");if(index.has("undo"))total+=index.getJSONObject("undo").getLong("bytes");if(total>MAX_TOTAL_BYTES)throw new IOException("Presets use the available 64 MB. Delete a saved preset before adding another.");
    }
    private void commit(JSONObject index)throws Exception {
        checkBudget(index);byte[] bytes=index.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>INDEX_BYTES)throw new IOException("Preset index is too large");write(index(),bytes);try{prune(index);}catch(Exception error){android.util.Log.w("NthPresets","Old preset cleanup deferred",error);}
    }
    private void prune(JSONObject index)throws Exception {
        Set<String> keep=new HashSet<>();JSONArray entries=index.getJSONArray("entries");for(int i=0;i<entries.length();i++)keep.add(entries.getJSONObject(i).getString("blob"));if(index.has("undo"))keep.add(index.getJSONObject("undo").getString("blob"));File[] files=directory.listFiles();if(files!=null)for(File f:files){String name=f.getName();String stem=name.endsWith(".bak")||name.endsWith(".new")?name.substring(0,name.length()-4):name;if(stem.endsWith(".json")){String id=stem.substring(0,stem.length()-5);if(PresetNames.identifier(id)&&!keep.contains(id))new AtomicFile(blob(id)).delete();}}
    }
    Listing list()throws Exception {synchronized(LOCK){JSONObject index=readIndex();List<Entry> entries=new ArrayList<>();JSONArray values=index.getJSONArray("entries");for(int i=0;i<values.length();i++)entries.add(new Entry(values.getJSONObject(i)));return new Listing(entries,index.has("undo"));}}
    private Entry find(JSONObject index,String id)throws Exception {JSONArray entries=index.getJSONArray("entries");for(int i=0;i<entries.length();i++){Entry e=new Entry(entries.getJSONObject(i));if(e.id.equals(id))return e;}throw new IOException("That preset is no longer available");}
    private void uniqueName(JSONObject index,String name,String except)throws Exception {JSONArray entries=index.getJSONArray("entries");for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);if(!e.getString("id").equals(except)&&PresetNames.same(name,e.getString("name")))throw new IOException("A preset already uses that name");}}
    private JSONObject metadata(String id,String name,Snapshot snapshot)throws Exception {return new JSONObject().put("id",id).put("name",PresetNames.checked(name)).put("blob",UUID.randomUUID().toString()).put("sha256",DesktopBackup.digest(snapshot.bytes)).put("bytes",snapshot.bytes.length).put("saved",System.currentTimeMillis()).put("scene",snapshot.scene).put("source",snapshot.source).put("pages",snapshot.prepared.pages.size()).put("folders",snapshot.prepared.folders).put("shortcuts",snapshot.prepared.shortcuts).put("widgets",snapshot.prepared.widgets.length()).put("cards",snapshot.prepared.cards).put("widgetIds",new JSONArray(snapshot.widgetIds)).put("shortcutKeys",new JSONArray(snapshot.shortcutKeys));}
    void save(String name,String replace,Snapshot snapshot)throws Exception {synchronized(LOCK){JSONObject index=readIndex();initialize(index);name=PresetNames.checked(name);uniqueName(index,name,replace);JSONArray entries=index.getJSONArray("entries"),next=new JSONArray();if(replace==null&&entries.length()>=MAX_PRESETS)throw new IOException("You can save up to 12 presets");JSONObject meta=metadata(replace==null?UUID.randomUUID().toString():find(index,replace).id,name,snapshot);boolean replaced=false;for(int i=0;i<entries.length();i++){JSONObject old=entries.getJSONObject(i);if(old.getString("id").equals(replace)){queue(index,old);next.put(meta);replaced=true;}else next.put(old);}if(!replaced)next.put(meta);index.put("entries",next);checkBudget(index);AtomicFile data=new AtomicFile(blob(meta.getString("blob")));try{write(data,snapshot.bytes);commit(index);}catch(Exception error){data.delete();throw error;}}}
    void rename(String id,String name)throws Exception {synchronized(LOCK){JSONObject index=readIndex();name=PresetNames.checked(name);uniqueName(index,name,id);find(index,id);JSONArray entries=index.getJSONArray("entries");for(int i=0;i<entries.length();i++)if(entries.getJSONObject(i).getString("id").equals(id))entries.getJSONObject(i).put("name",name);commit(index);}}
    void delete(String id)throws Exception {synchronized(LOCK){JSONObject index=readIndex();find(index,id);JSONArray entries=index.getJSONArray("entries"),next=new JSONArray();for(int i=0;i<entries.length();i++){JSONObject old=entries.getJSONObject(i);if(old.getString("id").equals(id))queue(index,old);else next.put(old);}index.put("entries",next);commit(index);}}
    private DesktopBackup.Prepared prepare(Entry e,SettingsModel model)throws Exception {byte[] bytes;try(InputStream in=new AtomicFile(blob(e.blob)).openRead()){bytes=WallpaperStore.read(in,DesktopBackup.MAX_BYTES);}if(bytes.length!=e.bytes||!DesktopBackup.digest(bytes).equals(e.json.getString("sha256")))throw new IOException("This preset is incomplete or damaged");return new DesktopBackup.Prepared(new JSONObject(new String(bytes,StandardCharsets.UTF_8)),model);}
    DesktopBackup.Prepared prepare(String id,SettingsModel model)throws Exception {synchronized(LOCK){return prepare(find(readIndex(),id),model);}}
    DesktopBackup.Prepared prepareUndo(SettingsModel model)throws Exception {synchronized(LOCK){JSONObject index=readIndex();if(!index.has("undo"))throw new IOException("There is no preset change to undo");return prepare(new Entry(index.getJSONObject("undo")),model);}}
    void remember(Snapshot current)throws Exception {synchronized(LOCK){JSONObject index=readIndex();initialize(index);if(index.has("undo"))queue(index,index.getJSONObject("undo"));JSONObject meta=metadata(UUID.randomUUID().toString(),"Previous desktop",current);index.put("undo",meta);checkBudget(index);AtomicFile data=new AtomicFile(blob(meta.getString("blob")));try{write(data,current.bytes);commit(index);}catch(Exception error){data.delete();throw error;}}}
    void clearUndo()throws Exception {synchronized(LOCK){JSONObject index=readIndex();if(index.has("undo")){queue(index,index.getJSONObject("undo"));index.remove("undo");commit(index);}}}
    private static Set<Integer> ids(JSONObject entry)throws Exception {Set<Integer> ids=new HashSet<>();JSONArray list=entry.getJSONArray("widgetIds");if(list.length()>300)throw new IOException("Invalid widget references");for(int i=0;i<list.length();i++){Object id=list.get(i);if(!(id instanceof Integer)||((Integer)id)<0)throw new IOException("Invalid widget identity");ids.add((Integer)id);}return ids;}
    private static Set<Integer> retained(JSONObject index)throws Exception {Set<Integer> keep=new HashSet<>();JSONArray entries=index.getJSONArray("entries");for(int i=0;i<entries.length();i++)keep.addAll(ids(entries.getJSONObject(i)));if(index.has("undo"))keep.addAll(ids(index.getJSONObject("undo")));return keep;}
    private void queue(JSONObject index,JSONObject entry)throws Exception {Set<Integer> all=new HashSet<>();JSONArray old=index.getJSONArray("gc");for(int i=0;i<old.length();i++)all.add(old.getInt(i));all.addAll(ids(entry));index.put("gc",new JSONArray(all));}
    static boolean references(Context context,int id){synchronized(LOCK){try{return retained(new DesktopPresets(context).readIndex()).contains(id);}catch(Exception invalid){return true;}}} // Preserve bindings if an index needs recovery.
    static Set<String> shortcutReferences(Context context){synchronized(LOCK){try{JSONObject index=new DesktopPresets(context).readIndex();JSONArray entries=new JSONArray(index.getJSONArray("entries").toString());if(index.has("undo"))entries.put(index.getJSONObject("undo"));Set<String> keys=new HashSet<>();for(int i=0;i<entries.length();i++){JSONArray list=entries.getJSONObject(i).optJSONArray("shortcutKeys");if(list!=null)for(int j=0;j<list.length();j++)keys.add(list.getString(j));}return keys;}catch(Exception invalid){return null;}}}
    void collectWidgets(LauncherStore store)throws Exception {synchronized(LOCK){JSONObject index=readIndex();JSONArray raw=index.getJSONArray("gc");if(raw.length()==0)return;Set<Integer> candidates=new HashSet<>(),keep=retained(index);for(int i=0;i<raw.length();i++)candidates.add(raw.getInt(i));for(String key:store.preferences.getAll().keySet())if(key.startsWith("widget_ids_page_"))for(String value:store.preferences.getString(key,"").split(","))try{keep.add(Integer.parseInt(value));}catch(NumberFormatException ignored){}for(DockStore.Slot slot:store.dock.slots)if(slot.widgetId>=0)keep.add(slot.widgetId);keep.add(store.preferences.getInt("pending_widget_id",-1));for(int hostId:new int[]{3047,3048}){LauncherWidgetHost host=new LauncherWidgetHost(context,hostId);for(int id:host.getAppWidgetIds())if(candidates.contains(id)&&!keep.contains(id))host.deleteAppWidgetId(id);}index.put("gc",new JSONArray());commit(index);}}
}
